{
	[AddComponentMenu("")]
	public class ActRotatorExample : UnityEngine.MonoBehaviour
	{
		[Range(1f, 100f)]
		public float speed = 5f;

		private void BMLFAKLIAJI()
		{
			base.transform.Rotate(1819f, speed * Time.deltaTime, 1978f);
		}

		private void JAPDAEJBPPJ()
		{
			base.transform.Rotate(1247f, speed * Time.deltaTime, 969f);
