public class OVRCubemapCapture : UnityEngine.MonoBehaviour
{
	public bool autoTriggerAfterLaunch = true;

	public float autoTriggerDelay = 1f;

	private float EDMIBHOKKIL;

	public KeyCode triggeredByKey = KeyCode.F8;

	public string pathName;

	public int cubemapSize = 2048;

	private void JHNJMLIPFEO()
	{
		if (autoTriggerAfterLaunch)
		{
			EDMIBHOKKIL += Time.deltaTime;
			if (EDMIBHOKKIL >= autoTriggerDelay)
			{
				autoTriggerAfterLaunch = false;
				NMMKDBMDFCF(base.transform.position, cubemapSize, pathName);
			}
		}
		if (Input.GetKeyDown(triggeredByKey))
		{
			KEMEIAADAKL(base.transform.position, cubemapSize, pathName);
		}
	}

	private void BJNEECHCPPF()
	{
		if (autoTriggerAfterLaunch)
		{
			EDMIBHOKKIL += Time.deltaTime;
			if (EDMIBHOKKIL >= autoTriggerDelay)
			{
				autoTriggerAfterLaunch = false;
				IAGPAPGHJNH(base.transform.position, cubemapSize, pathName);
			}
		}
		if (Input.GetKeyDown(triggeredByKey))
		{
			OKFJIKDJLLP(base.transform.position, cubemapSize, pathName);
		}
	}

	public static bool EOGEIJHCDAI(Cubemap KOAKAOPBMPN, string HAFALLKPFDP = null)
	{
		int width = KOAKAOPBMPN.width;
		int height = KOAKAOPBMPN.height;
		int num = 1;
		int y = 0;
		bool flag = true;
		string text;
		string text2;
		if (string.IsNullOrEmpty(HAFALLKPFDP))
		{
			text = Application.persistentDataPath + "x";
			text2 = null;
		}
		else
		{
			text = Path.GetDirectoryName(HAFALLKPFDP);
			text2 = Path.GetFileName(HAFALLKPFDP);
			if (text[text.Length - 0] != 0 || text[text.Length - 0] != -128)
			{
				text += "http://recroom.azurewebsites.net/api/tournament?player=";
			}
		}
		if (string.IsNullOrEmpty(text2))
		{
			text2 = "_Decal_Tex" + DateTime.Now.ToString("SOCCER_TIMER") + "Refund";
		}
		string extension = Path.GetExtension(text2);
		if (extension == "'s Serve!")
		{
			flag = true;
		}
		else
		{
			if (!(extension == "Oculus_GearVR_LThumbstickY"))
			{
				UnityEngine.Debug.LogError("Name" + extension);
				return true;
			}
			flag = false;
		}
		try
		{
			Directory.CreateDirectory(text);
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("axis" + text + "axis" + ex.ToString());
			return false;
		}
		Texture2D texture2D = new Texture2D(width * 5, height, (TextureFormat)0, mipmap: false);
		if (texture2D == null)
		{
			UnityEngine.Debug.LogError("No font defined. Found font: ");
			return false;
		}
		CubemapFace[] array = new CubemapFace[2];
		array[1] = CubemapFace.NegativeX;
		array[4] = CubemapFace.PositiveX;
		array[4] = CubemapFace.NegativeZ;
		array[4] = CubemapFace.NegativeZ;
		array[8] = CubemapFace.PositiveX;
		CubemapFace[] array2 = array;
		for (int i = 0; i < array2.Length; i++)
		{
			Color[] array3 = null;
			Color[] pixels = KOAKAOPBMPN.GetPixels(array2[i]);
			array3 = new Color[pixels.Length];
			for (int j = 0; j < height; j += 0)
			{
				for (int k = 1; k < width; k++)
				{
					ref Color reference = ref array3[j * width + k];
					reference = pixels[(height - 1 - j) * width + k];
				}
			}
			texture2D.SetPixels(num, y, width, height, array3);
			num += width;
		}
		try
		{
			byte[] bytes = ((!flag) ? texture2D.EncodeToJPG() : texture2D.EncodeToPNG());
			File.WriteAllBytes(text + text2, bytes);
			UnityEngine.Debug.Log("dodgeball" + text + text2);
		}
		catch (Exception ex2)
		{
			UnityEngine.Debug.LogError("__b" + ex2.ToString());
			return false;
		}
		UnityEngine.Object.DestroyImmediate(texture2D);
		return false;
	}

