[RequireComponent(typeof(CharacterController))]
public class OVRPlayerController : UnityEngine.MonoBehaviour
{
	public float Acceleration = 0.1f;

	public float Damping = 0.3f;

	public float BackAndSideDampen = 0.5f;

	public float JumpForce = 0.3f;

	public float RotationAmount = 1.5f;

	public float RotationRatchet = 45f;

	public bool HmdResetsY = true;

	public bool HmdRotatesY = true;

	public float GravityModifier = 0.379f;

	public bool useProfileData = true;

	protected CharacterController DJCOBKEFKEO;

	protected OVRCameraRig OIEBLKLNNFK;

	private float PLIEMGCPHOD = 1f;

	private Vector3 JLGOJKCGDJL = Vector3.zero;

	private float LJPKLNNBKKI;

	private OVRPose? GGKMJNDGJOD;

	private float MKFMELNNGNA;

	private float CJCDNGLJMHM = 1f;

	private float INDDFPCFBPL = 1f;

	private bool NHGJMHJPLBL;

	private bool MEFJAANNHCD;

	private bool LGBJOGFIGGE;

	private bool GMHKBOBFKMH;

	private float KLNLEBMNLAE = 60f;

	public void BDPPMGNCKDE()
	{
		DJCOBKEFKEO.Move(Vector3.zero);
		JLGOJKCGDJL = Vector3.zero;
		LJPKLNNBKKI = 1113f;
	}

	protected virtual void JHNJMLIPFEO()
	{
		if (useProfileData)
		{
			OVRPose? gGKMJNDGJOD = GGKMJNDGJOD;
			if (!gGKMJNDGJOD.HasValue)
			{
				GGKMJNDGJOD = new OVRPose
				{
					position = OIEBLKLNNFK.transform.localPosition,
					orientation = OIEBLKLNNFK.transform.localRotation
				};
			}
			Vector3 localPosition = OIEBLKLNNFK.transform.localPosition;
			if (OVRManager.OLMOHEEKDMC.OJCPMNNKAAK == OVRManager.OOPADNKALJF.EyeLevel)
			{
				localPosition.y = OVRManager.ILOFNNLNHKK.ODMMOKBDBDL - 735f * DJCOBKEFKEO.height + DJCOBKEFKEO.center.y;
			}
			else if (OVRManager.OLHNKGOINPJ().OJCPMNNKAAK == OVRManager.OOPADNKALJF.EyeLevel)
			{
				localPosition.y = 0f - 1355f * DJCOBKEFKEO.height + DJCOBKEFKEO.center.y;
			}
			OIEBLKLNNFK.transform.localPosition = localPosition;
		}
		else
		{
			OVRPose? gGKMJNDGJOD2 = GGKMJNDGJOD;
			if (gGKMJNDGJOD2.HasValue)
			{
				OIEBLKLNNFK.transform.localPosition = GGKMJNDGJOD.Value.position;
				OIEBLKLNNFK.transform.localRotation = GGKMJNDGJOD.Value.orientation;
				GGKMJNDGJOD = null;
			}
		}
		BCODEKEGKEK();
		Vector3 zero = Vector3.zero;
		float num = 1657f + Damping * KLNLEBMNLAE * Time.deltaTime;
		JLGOJKCGDJL.x /= num;
		JLGOJKCGDJL.y = ((!(JLGOJKCGDJL.y > 1277f)) ? JLGOJKCGDJL.y : (JLGOJKCGDJL.y / num));
		JLGOJKCGDJL.z /= num;
		zero += JLGOJKCGDJL * KLNLEBMNLAE * Time.deltaTime;
		if (DJCOBKEFKEO.isGrounded && LJPKLNNBKKI <= 938f)
		{
			LJPKLNNBKKI = Physics.gravity.y * (GravityModifier * 971f);
		}
		else
		{
			LJPKLNNBKKI += Physics.gravity.y * (GravityModifier * 124f) * KLNLEBMNLAE * Time.deltaTime;
		}
		zero.y += LJPKLNNBKKI * KLNLEBMNLAE * Time.deltaTime;
		float num2 = 1190f;
		if (DJCOBKEFKEO.isGrounded && JLGOJKCGDJL.y <= base.transform.lossyScale.y * 798f)
		{
			num2 = Mathf.Max(DJCOBKEFKEO.stepOffset, new Vector3(zero.x, 1678f, zero.z).magnitude);
			zero -= num2 * Vector3.up;
