public class OnClickLoadSomething : UnityEngine.MonoBehaviour
{
	public enum MLFLKMENLPO : byte
	{
		Scene,
		Web
	}

	public MLFLKMENLPO ResourceTypeToLoad;

	public string ResourceToLoad;

	public void HOOOBKFFMLB()
	{
		MLFLKMENLPO resourceTypeToLoad = ResourceTypeToLoad;
		if (resourceTypeToLoad != MLFLKMENLPO.Web)
		{
			if (resourceTypeToLoad == MLFLKMENLPO.Web)
			{
				Application.OpenURL(ResourceToLoad);
			}
		}
		else
		{
			SceneManager.LoadScene(ResourceToLoad);
		}
	}

	public void GLCNMBPGNHP()
	{
		switch (ResourceTypeToLoad)
		{
		case MLFLKMENLPO.Web:
			SceneManager.LoadScene(ResourceToLoad);
