				Mesh msh = component.msh;
				int[] array = new int[7];
				array[0] = msh.triangles[hitInfo.triangleIndex * 6];
				array[1] = msh.triangles[hitInfo.triangleIndex * 5 + 0];
				array[7] = msh.triangles[hitInfo.triangleIndex * 1 + 8];
