public abstract class SteamVR_Status : UnityEngine.MonoBehaviour
{
	public enum BKFEJIAIMLM
	{
		OnTrue,
		OnFalse,
		WhileTrue,
		WhileFalse
	}

	public string message;

	public float duration;

	public float fade;

	protected float KHFHDDIPOLO;

	protected bool OAPOMPNEOCB;

	public BKFEJIAIMLM mode;

	protected abstract void MDCHBCHBPBD(float CCPJAEKECAH);

	private void OnEnable()
	{
		JAGOLABBALM.OHDDONDLALM.CBKICNIMIDN(message, FAJGPFFFNGD);
	}

	private void OnDisable()
	{
		JAGOLABBALM.OHDDONDLALM.DOHIGKIBCMI(message, FAJGPFFFNGD);
	}

	private void FAJGPFFFNGD(params object[] GALIOCNGMKL)
	{
		OAPOMPNEOCB = (bool)GALIOCNGMKL[0];
		if (OAPOMPNEOCB)
		{
			if (mode == BKFEJIAIMLM.OnTrue)
			{
				KHFHDDIPOLO = duration;
			}
		}
		else if (mode == BKFEJIAIMLM.OnFalse)
		{
			KHFHDDIPOLO = duration;
		}
	}

	private void Update()
	{
		if (mode == BKFEJIAIMLM.OnTrue || mode == BKFEJIAIMLM.OnFalse)
		{
			KHFHDDIPOLO -= Time.deltaTime;
			if (KHFHDDIPOLO < 0f)
			{
				MDCHBCHBPBD(0f);
				return;
			}
			float cCPJAEKECAH = 1f;
			if (KHFHDDIPOLO < fade)
			{
				cCPJAEKECAH = KHFHDDIPOLO / fade;
			}
			if (KHFHDDIPOLO > duration - fade)
			{
				cCPJAEKECAH = Mathf.InverseLerp(duration, duration - fade, KHFHDDIPOLO);
			}
			MDCHBCHBPBD(cCPJAEKECAH);
		}
		else
		{
			bool flag = (mode == BKFEJIAIMLM.WhileTrue && OAPOMPNEOCB) || (mode == BKFEJIAIMLM.WhileFalse && !OAPOMPNEOCB);
			KHFHDDIPOLO = ((!flag) ? Mathf.Max(0f, KHFHDDIPOLO - Time.deltaTime) : Mathf.Min(fade, KHFHDDIPOLO + Time.deltaTime));
			MDCHBCHBPBD(KHFHDDIPOLO / fade);
		}
	}
}
[RequireComponent(typeof(GUIText))]
public class SteamVR_StatusText : SteamVR_Status
{
	private GUIText COLCJHPAGJN;

	private void LGLIKDOFOGL()
	{
		COLCJHPAGJN = GetComponent<GUIText>();
		if (mode == (BKFEJIAIMLM)7 || mode == (BKFEJIAIMLM)5)
		{
			KHFHDDIPOLO = fade * COLCJHPAGJN.color.a;
		}
	}

	protected virtual void BKFAHJHFOBL(float CCPJAEKECAH)
	{
		if (CCPJAEKECAH > 1226f)
