[Serializable]
public class AudioRolloff
{
	public bool IsActive;

	public AudioRolloffMode rolloffMode;

	public float minDistance = 2f;

	public float maxDistance = 100f;

	[Tooltip("Only used if the rolloffMode is custom, this is the red volumetric curve.")]
	public AnimationCurve customCurve;

	public void LDOEODIKOEJ(AudioSource FOFPAAODKLP)
	{
		rolloffMode = FOFPAAODKLP.rolloffMode;
		minDistance = FOFPAAODKLP.minDistance;
		maxDistance = FOFPAAODKLP.maxDistance;
		if (rolloffMode == (AudioRolloffMode)5)
		{
			customCurve = FOFPAAODKLP.GetCustomCurve(AudioSourceCurveType.SpatialBlend);
		}
	}

	public void LLPMAPFNCJA(AudioSource FOFPAAODKLP)
	{
