	private void DOCFABHBKMF(OutfitItem CBCGAIKEIDP)
	{
		SkinnedMeshRenderer targetSkinnedMesh = null;
		switch (CBCGAIKEIDP.Type)
		{
		case OutfitManager.AHPENMGAFHM.Hat:
		case OutfitManager.AHPENMGAFHM.BackHead:
		case OutfitManager.AHPENMGAFHM.Hair:
			targetSkinnedMesh = face;
			break;
		case OutfitManager.AHPENMGAFHM.Eye:
			targetSkinnedMesh = eyes;
			break;
		case OutfitManager.AHPENMGAFHM.Mouth:
			targetSkinnedMesh = mouth;
			break;
		case OutfitManager.AHPENMGAFHM.Neck:
		case OutfitManager.AHPENMGAFHM.Shirt:
		case OutfitManager.AHPENMGAFHM.Belt:
		case OutfitManager.AHPENMGAFHM.Pocket:
		case OutfitManager.AHPENMGAFHM.TeamJersey:
			targetSkinnedMesh = torso;
			break;
		case OutfitManager.AHPENMGAFHM.Wrist:
		case OutfitManager.AHPENMGAFHM.Glove:
		case OutfitManager.AHPENMGAFHM.Watch:
		case OutfitManager.AHPENMGAFHM.TeamWrist:
			if (CBCGAIKEIDP.CurrentBodyPart == Player.ENGBBHKECNJ.LeftHand)
			{
				targetSkinnedMesh = leftHand;
				break;
			}
			if (CBCGAIKEIDP.CurrentBodyPart == Player.ENGBBHKECNJ.RightHand)
			{
				targetSkinnedMesh = rightHand;
				break;
			}
			UnityEngine.Debug.LogError(string.Concat("An outfit (", CBCGAIKEIDP, ") with hand type is being placed to an incorrect body part. ", CBCGAIKEIDP.CurrentBodyPart));
			break;
		default:
			throw new Exception("PlayerOutfit.SetOutfitTarget can not set target for this outfit " + CBCGAIKEIDP);
		}
		CBCGAIKEIDP.SetTargetSkinnedMesh(targetSkinnedMesh);
	}

