public static class MIHHJOPKBDM
{
	private const int EHBECJBKDIF = 256;

	private const int OBMPKCDGDHB = 1000;

	public static byte[] EPKIFOEOIEC(byte[] DNMIOAMBCKI, string GINGDECNHEA)
	{
		byte[] array = IDJBNJLFOFI();
		byte[] array2 = IDJBNJLFOFI();
		Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(GINGDECNHEA, array, 1000);
		byte[] bytes = rfc2898DeriveBytes.GetBytes(32);
		using RijndaelManaged rijndaelManaged = new RijndaelManaged();
		rijndaelManaged.BlockSize = 256;
		rijndaelManaged.Mode = CipherMode.CBC;
		rijndaelManaged.Padding = PaddingMode.PKCS7;
		using ICryptoTransform transform = rijndaelManaged.CreateEncryptor(bytes, array2);
		using MemoryStream memoryStream = new MemoryStream();
		using CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write);
		cryptoStream.Write(DNMIOAMBCKI, 0, DNMIOAMBCKI.Length);
		cryptoStream.FlushFinalBlock();
		byte[] first = array;
		first = Enumerable.Concat(first, array2).ToArray();
		first = Enumerable.Concat(first, memoryStream.ToArray()).ToArray();
		memoryStream.Close();
		cryptoStream.Close();
		return first;
	}

	public static byte[] ACGNDKCFFOM(byte[] AOJFNBLONNC, string GINGDECNHEA)
	{
		byte[] salt = AOJFNBLONNC.Take(32).ToArray();
		byte[] rgbIV = AOJFNBLONNC.Skip(32).Take(32).ToArray();
		byte[] array = AOJFNBLONNC.Skip(64).Take(AOJFNBLONNC.Length - 64).ToArray();
		Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(GINGDECNHEA, salt, 1000);
		byte[] bytes = rfc2898DeriveBytes.GetBytes(32);
		using RijndaelManaged rijndaelManaged = new RijndaelManaged();
		rijndaelManaged.BlockSize = 256;
		rijndaelManaged.Mode = CipherMode.CBC;
		rijndaelManaged.Padding = PaddingMode.PKCS7;
		using ICryptoTransform transform = rijndaelManaged.CreateDecryptor(bytes, rgbIV);
		using MemoryStream memoryStream = new MemoryStream(array);
		using CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Read);
		byte[] array2 = new byte[array.Length];
		cryptoStream.Read(array2, 0, array2.Length);
		memoryStream.Close();
		cryptoStream.Close();
		return array2;
	}

	private static byte[] IDJBNJLFOFI()
	{
		byte[] array = new byte[32];
		RNGCryptoServiceProvider rNGCryptoServiceProvider = new RNGCryptoServiceProvider();
		rNGCryptoServiceProvider.GetBytes(array);
		return array;
	}
