	private void FIHKIFPCBOM(float PGODJHAOECE, float DIPFFGEMNFH, float IMLFBLDGBCN, Vector3 IIDJHDBHGHG, Vector3 JBCPFANOKNE, Quaternion MDMGJBANNNG, Quaternion LOCDEMAEFBP)
	{
		Vector3 a = Vector3.Project(IIDJHDBHGHG, Vector3.up);
		Vector3 b = Vector3.Project(JBCPFANOKNE, Vector3.up);
		Vector3 vector = Vector3.ProjectOnPlane(IIDJHDBHGHG, Vector3.up);
		Vector3 vector2 = Vector3.ProjectOnPlane(JBCPFANOKNE, Vector3.up);
		float magnitude = vector.magnitude;
		vector /= magnitude;
		float magnitude2 = vector2.magnitude;
		vector2 /= magnitude2;
		float num = Vector3.Angle(vector, vector2);
		if (num >= Mathf.Epsilon && Vector3.Dot(Vector3.Cross(vector, vector2), Vector3.up) < 0f)
		{
			num = 360f - num;
