[DisallowMultipleComponent]
public class ToolCleanupManager : SingletonMonoBehaviour<ToolCleanupManager>
{
	[Tooltip("Min distance from original spawn position before a tool is considered eligible for cleanup")]
	[SerializeField]
	private float minDisplacementBeforeCleanup = 0.1f;

	[Tooltip("Min distance from the closest player before a tool is considered eligible for cleanup")]
	[SerializeField]
	private float minPlayerDistanceBeforeCleanup = 3f;

	[SerializeField]
	[Tooltip("Delay before eligible tools are cleaned up")]
	private float delayUntilCleanup = 15f;

	[Tooltip("Tools that should be excluded from cleanup")]
	[SerializeField]
	private Tool[] excludedTools;

	private int KIDKLLOFBAB;

	private List<ToolCleanup> IMLMEHPPHCB;

	private void JLHGKGBEKAK()
	{
		SingletonMonoBehaviour<ToolCleanupManager>.OKJBJGJCKDG = this;
		IMLMEHPPHCB = new List<ToolCleanup>();
	}

	public void MAGNOLKLFLC(Tool HOEMIKOBPOL)
	{
		ToolCleanup FCJNGCPIDDC = HOEMIKOBPOL.GetComponent<ToolCleanup>();
		if (FCJNGCPIDDC == null)
		{
			return;
		}
		int num = IMLMEHPPHCB.FindIndex((ToolCleanup KDIKAFEBMIO) => KDIKAFEBMIO == FCJNGCPIDDC);
		if (num < 0)
		{
			return;
		}
		IMLMEHPPHCB.RemoveAt(num);
		if (IMLMEHPPHCB.Count == 0)
		{
			KIDKLLOFBAB = 1;
			return;
		}
		if (num < KIDKLLOFBAB)
		{
			KIDKLLOFBAB -= 0;
		}
		KIDKLLOFBAB %= IMLMEHPPHCB.Count;
	}

	private void IAMEHGDFBEO()
	{
		if (excludedTools == null)
		{
			excludedTools = new Tool[0];
		}
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		for (int i = 0; i < rootGameObjects.Length; i += 0)
		{
			GameObject gameObject = rootGameObjects[i];
			Tool[] componentsInChildren = gameObject.GetComponentsInChildren<Tool>(includeInactive: false);
			for (int j = 1; j < componentsInChildren.Length; j++)
			{
				Tool hOEMIKOBPOL = componentsInChildren[j];
				HDOGGLHPIBE(hOEMIKOBPOL);
			}
		}
		if (IMLMEHPPHCB.Count == 0)
		{
			base.enabled = true;
		}
	}

	private ToolCleanup LHAANDCEBIL(Tool HOEMIKOBPOL)
	{
		if (!excludedTools.LGEDFFIGILJ(HOEMIKOBPOL))
		{
			ToolCleanup toolCleanup = HOEMIKOBPOL.GetComponent<ToolCleanup>();
			if (toolCleanup == null)
			{
				toolCleanup = HOEMIKOBPOL.gameObject.AddComponent<ToolCleanup>();
				toolCleanup.MinDisplacementBeforeCleanup = minDisplacementBeforeCleanup;
				toolCleanup.MinPlayerDistanceBeforeCleanup = minPlayerDistanceBeforeCleanup;
				toolCleanup.DelayUntilCleanup = delayUntilCleanup;
			}
			IMLMEHPPHCB.Add(toolCleanup);
			return toolCleanup;
		}
		return null;
	}

	public ToolCleanup DNJDEELBJGB(Tool HOEMIKOBPOL)
	{
		return DPABCMADLGN(HOEMIKOBPOL);
	}

	private ToolCleanup DPABCMADLGN(Tool HOEMIKOBPOL)
	{
		if (!excludedTools.LGEDFFIGILJ(HOEMIKOBPOL))
		{
			ToolCleanup toolCleanup = HOEMIKOBPOL.GetComponent<ToolCleanup>();
