			}
			Controller.BIODADDBIOI = AMKKEDFCMJM;
			if (TabHeaderButton != null && TabHeaderButton.image != null)
			{
				TabHeaderButton.image.color = ((!AMKKEDFCMJM) ? FDMLKMEEDCD : selectedHeaderButtonColor);
			}
			OBJALDHCHLF();
			INJBMKIFPEB.MarkDirty();
