		public GBIPCMMGIJG(string GAAMIIMINFA, int LBCOFPAFPID, Color[] ICHAABBIFDN, float GANKEDOGEMH, float? JHPGAMBEIFD = null, float? AFDIGFHHDHD = null)
		{
			this.GAAMIIMINFA = GAAMIIMINFA;
			this.GANKEDOGEMH = GANKEDOGEMH;
			this.JHPGAMBEIFD = JHPGAMBEIFD;
			this.AFDIGFHHDHD = AFDIGFHHDHD;
			for (int i = 0; i < LBCOFPAFPID && i < ICHAABBIFDN.Length; i++)
			{
				MFIEADHBGHH.Add(new KOHCIBKJGHM
				{
					POKEFPLAPAG = ICHAABBIFDN[i]
				});
			}
		}

		public void PIDEDFMLILM(float[] OJPCNDLOMNG)
		{
			for (int i = 0; i < OJPCNDLOMNG.Length && i < MFIEADHBGHH.Count; i++)
			{
				while (MFIEADHBGHH[i].AKCPHHBNCGN.Count > 0 && Time.realtimeSinceStartup - MFIEADHBGHH[i].AKCPHHBNCGN[1].x > GANKEDOGEMH)
				{
					MFIEADHBGHH[i].AKCPHHBNCGN.RemoveAt(1);
				}
				MFIEADHBGHH[i].AKCPHHBNCGN.Add(new Vector2(Time.realtimeSinceStartup, OJPCNDLOMNG[i]));
			}
		}
	}
