public static class DOFKBHCPEDH
{
	private static Texture2D DPONGKHMNPK;

	private static Texture2D JOMNGICCOEE;

	private static Material IAILAODDLJC;

	private static Material BHHIJOLAHGL;

	private static Rect EEPNLECHFCI;

	static DOFKBHCPEDH()
	{
		DPONGKHMNPK = null;
		JOMNGICCOEE = null;
		IAILAODDLJC = null;
		BHHIJOLAHGL = null;
		EEPNLECHFCI = new Rect(0f, 0f, 1f, 1f);
		IFAGCGEBLCF();
	}

	public static void DIGBJPCFHDM(Vector2 ONBPMLCDHKC, Vector2 GGDAFFCLKBB, Color KAKIJHBPHDL, float CLNICLJBMNO, bool HPCFDNFPBOE)
	{
		float num = GGDAFFCLKBB.x - ONBPMLCDHKC.x;
		float num2 = GGDAFFCLKBB.y - ONBPMLCDHKC.y;
		float num3 = Mathf.Sqrt(num * num + num2 * num2);
		if (!(num3 < 0.001f))
		{
			Texture2D texture;
			Material mat;
			if (HPCFDNFPBOE)
			{
				CLNICLJBMNO *= 3f;
				texture = DPONGKHMNPK;
				mat = BHHIJOLAHGL;
			}
			else
			{
				texture = JOMNGICCOEE;
				mat = IAILAODDLJC;
			}
			float num4 = CLNICLJBMNO * num2 / num3;
			float num5 = CLNICLJBMNO * num / num3;
			Matrix4x4 identity = Matrix4x4.identity;
			identity.m00 = num;
			identity.m01 = 0f - num4;
			identity.m03 = ONBPMLCDHKC.x + 0.5f * num4;
			identity.m10 = num2;
			identity.m11 = num5;
			identity.m13 = ONBPMLCDHKC.y - 0.5f * num5;
			GL.PushMatrix();
			GL.MultMatrix(identity);
			Graphics.DrawTexture(EEPNLECHFCI, texture, EEPNLECHFCI, 0, 0, 0, 0, KAKIJHBPHDL, mat);
			GL.PopMatrix();
		}
	}

	public static void AHEBDBMHODD(IEnumerable<Vector2> OMBNDPKANJI, Color KAKIJHBPHDL, float CLNICLJBMNO, bool HPCFDNFPBOE)
	{
		bool flag = false;
		Vector2 oNBPMLCDHKC = Vector2.zero;
		foreach (Vector2 item in OMBNDPKANJI)
		{
			if (flag)
			{
				DIGBJPCFHDM(oNBPMLCDHKC, item, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE);
			}
			oNBPMLCDHKC = item;
			flag = true;
		}
	}

	public static void GCDPLKHBCBI(Vector2 LELDINOIKEG, int GBPEFMCMIEJ, Color KAKIJHBPHDL, float CLNICLJBMNO, int KDFGFFFJEDO)
	{
		GCDPLKHBCBI(LELDINOIKEG, GBPEFMCMIEJ, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE: false, KDFGFFFJEDO);
	}

	public static void GCDPLKHBCBI(Vector2 LELDINOIKEG, int GBPEFMCMIEJ, Color KAKIJHBPHDL, float CLNICLJBMNO, bool HPCFDNFPBOE, int KDFGFFFJEDO)
	{
		float num = (float)GBPEFMCMIEJ / 2f;
		Vector2 vector = new Vector2(LELDINOIKEG.x, LELDINOIKEG.y - (float)GBPEFMCMIEJ);
		Vector2 kIGADOHKKEG = new Vector2(LELDINOIKEG.x - num, LELDINOIKEG.y - (float)GBPEFMCMIEJ);
		Vector2 jOAOAPEIOPN = new Vector2(LELDINOIKEG.x + num, LELDINOIKEG.y - (float)GBPEFMCMIEJ);
		Vector2 vector2 = new Vector2(LELDINOIKEG.x + (float)GBPEFMCMIEJ, LELDINOIKEG.y);
		Vector2 kIGADOHKKEG2 = new Vector2(LELDINOIKEG.x + (float)GBPEFMCMIEJ, LELDINOIKEG.y - num);
		Vector2 jOAOAPEIOPN2 = new Vector2(LELDINOIKEG.x + (float)GBPEFMCMIEJ, LELDINOIKEG.y + num);
		Vector2 vector3 = new Vector2(LELDINOIKEG.x, LELDINOIKEG.y + (float)GBPEFMCMIEJ);
		Vector2 jOAOAPEIOPN3 = new Vector2(LELDINOIKEG.x - num, LELDINOIKEG.y + (float)GBPEFMCMIEJ);
		Vector2 kIGADOHKKEG3 = new Vector2(LELDINOIKEG.x + num, LELDINOIKEG.y + (float)GBPEFMCMIEJ);
		Vector2 vector4 = new Vector2(LELDINOIKEG.x - (float)GBPEFMCMIEJ, LELDINOIKEG.y);
		Vector2 jOAOAPEIOPN4 = new Vector2(LELDINOIKEG.x - (float)GBPEFMCMIEJ, LELDINOIKEG.y - num);
		Vector2 kIGADOHKKEG4 = new Vector2(LELDINOIKEG.x - (float)GBPEFMCMIEJ, LELDINOIKEG.y + num);
		CHGDIAAFPPF(vector, jOAOAPEIOPN, vector2, kIGADOHKKEG2, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE, KDFGFFFJEDO);
		CHGDIAAFPPF(vector2, jOAOAPEIOPN2, vector3, kIGADOHKKEG3, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE, KDFGFFFJEDO);
		CHGDIAAFPPF(vector3, jOAOAPEIOPN3, vector4, kIGADOHKKEG4, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE, KDFGFFFJEDO);
		CHGDIAAFPPF(vector4, jOAOAPEIOPN4, vector, kIGADOHKKEG, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE, KDFGFFFJEDO);
	}

	public static void CHGDIAAFPPF(Vector2 BFJPDJKFHON, Vector2 JOAOAPEIOPN, Vector2 FBHDPACICAK, Vector2 KIGADOHKKEG, Color KAKIJHBPHDL, float CLNICLJBMNO, bool HPCFDNFPBOE, int HLADFLKJMIJ)
	{
		Vector2 oNBPMLCDHKC = KLFOLNJMPMK(BFJPDJKFHON, JOAOAPEIOPN, FBHDPACICAK, KIGADOHKKEG, 0f);
		for (int i = 1; i < HLADFLKJMIJ + 1; i++)
		{
			Vector2 vector = KLFOLNJMPMK(BFJPDJKFHON, JOAOAPEIOPN, FBHDPACICAK, KIGADOHKKEG, (float)i / (float)HLADFLKJMIJ);
			DIGBJPCFHDM(oNBPMLCDHKC, vector, KAKIJHBPHDL, CLNICLJBMNO, HPCFDNFPBOE);
			oNBPMLCDHKC = vector;
		}
	}

	private static Vector2 KLFOLNJMPMK(Vector2 FBMBLFHCLIF, Vector2 CEMEIHDCBHN, Vector2 NEPCJAMLNOC, Vector2 GPGKOPLGPPO, float BHFNEOEPKGC)
	{
		float num = 1f - BHFNEOEPKGC;
		return num * num * num * FBMBLFHCLIF + 3f * num * num * BHFNEOEPKGC * CEMEIHDCBHN + 3f * num * BHFNEOEPKGC * BHFNEOEPKGC * GPGKOPLGPPO + BHFNEOEPKGC * BHFNEOEPKGC * BHFNEOEPKGC * NEPCJAMLNOC;
	}

	private static void IFAGCGEBLCF()
	{
		if (JOMNGICCOEE == null)
		{
			JOMNGICCOEE = new Texture2D(1, 1, TextureFormat.ARGB32, mipmap: false);
			JOMNGICCOEE.SetPixel(0, 1, Color.white);
			JOMNGICCOEE.Apply();
		}
		if (DPONGKHMNPK == null)
		{
			DPONGKHMNPK = new Texture2D(1, 3, TextureFormat.ARGB32, mipmap: false);
			DPONGKHMNPK.SetPixel(0, 0, new Color(1f, 1f, 1f, 0f));
			DPONGKHMNPK.SetPixel(0, 1, Color.white);
			DPONGKHMNPK.SetPixel(0, 2, new Color(1f, 1f, 1f, 0f));
			DPONGKHMNPK.Apply();
		}
		IAILAODDLJC = (Material)typeof(GUI).GetMethod("get_blitMaterial", BindingFlags.Static | BindingFlags.NonPublic).Invoke(null, null);
		BHHIJOLAHGL = (Material)typeof(GUI).GetMethod("get_blendMaterial", BindingFlags.Static | BindingFlags.NonPublic).Invoke(null, null);
	}
}
