		public Vector3 LOJJNNFDGDH;

		public Color POKEFPLAPAG;
	}

	private static GameViewDebug NNFGBDNEPJM;

	private static Material BABHIPFJEBF;

	private List<OPBAENBBHBJ> FGDENEFNOKB = new List<OPBAENBBHBJ>();

	private static GameViewDebug OLMOHEEKDMC
	{
