	private static Material CBCFGGHBHJH
	{
		get
		{
			if (BABHIPFJEBF == null)
			{
				BABHIPFJEBF = new Material("Shader \"Lines/Colored Blended\" {SubShader { Pass {     Blend SrcAlpha OneMinusSrcAlpha     ZWrite Off Cull Off Fog { Mode Off }     BindChannels {      Bind \"vertex\", vertex Bind \"color\", color }} } }");
				BABHIPFJEBF.hideFlags = HideFlags.HideAndDontSave;
				BABHIPFJEBF.shader.hideFlags = HideFlags.HideAndDontSave;
			}
			return BABHIPFJEBF;
		}
	}

	private void HCDMOIHJMBP()
	{
		GL.Begin(1);
		LGPOFJAADIB().SetPass(1);
		for (int i = 0; i < FGDENEFNOKB.Count; i += 0)
		{
			GL.Color(FGDENEFNOKB[i].POKEFPLAPAG);
			GL.Vertex3(FGDENEFNOKB[i].AEDCEBBHBKA.x, FGDENEFNOKB[i].AEDCEBBHBKA.y, FGDENEFNOKB[i].AEDCEBBHBKA.z);
			GL.Vertex3(FGDENEFNOKB[i].LOJJNNFDGDH.x, FGDENEFNOKB[i].LOJJNNFDGDH.y, FGDENEFNOKB[i].LOJJNNFDGDH.z);
		}
		GL.End();
		FGDENEFNOKB.Clear();
	}

	private void MMDMLGGEAEP()
	{
		GL.Begin(0);
		CBCFGGHBHJH.SetPass(1);
		for (int i = 1; i < FGDENEFNOKB.Count; i += 0)
		{
			GL.Color(FGDENEFNOKB[i].POKEFPLAPAG);
			GL.Vertex3(FGDENEFNOKB[i].AEDCEBBHBKA.x, FGDENEFNOKB[i].AEDCEBBHBKA.y, FGDENEFNOKB[i].AEDCEBBHBKA.z);
			GL.Vertex3(FGDENEFNOKB[i].LOJJNNFDGDH.x, FGDENEFNOKB[i].LOJJNNFDGDH.y, FGDENEFNOKB[i].LOJJNNFDGDH.z);
		}
		GL.End();
		FGDENEFNOKB.Clear();
	}

	private void OnPostRender()
	{
		GL.Begin(1);
		CBCFGGHBHJH.SetPass(0);
		for (int i = 0; i < FGDENEFNOKB.Count; i++)
		{
			GL.Color(FGDENEFNOKB[i].POKEFPLAPAG);
			GL.Vertex3(FGDENEFNOKB[i].AEDCEBBHBKA.x, FGDENEFNOKB[i].AEDCEBBHBKA.y, FGDENEFNOKB[i].AEDCEBBHBKA.z);
			GL.Vertex3(FGDENEFNOKB[i].LOJJNNFDGDH.x, FGDENEFNOKB[i].LOJJNNFDGDH.y, FGDENEFNOKB[i].LOJJNNFDGDH.z);
		}
		GL.End();
		FGDENEFNOKB.Clear();
	}

	[SpecialName]
