	private void JIBJGCDGPDI()
	{
		Texture2D texture2D = null;
		switch (ControllerIO.JEBCEPEAAJE)
		{
		case ControllerIO.FHOMPKCFMGB.Debug:
			texture2D = steamVrVive;
			break;
		case ControllerIO.FHOMPKCFMGB.SteamVR_Vive:
			texture2D = steamVrOculus;
			break;
		case ControllerIO.FHOMPKCFMGB.SteamVR_Oculus:
			texture2D = oculus;
			break;
		}
		if (texture2D == null)
		{
			texture2D = defaultTexture;
		}
		if (texture2D != null)
		{
			renderer.material.mainTexture = texture2D;
		}
	}

